answer
\begin{align*} S_3 &= \frac{S_1 \cdot S_2}{S_1 + S_2} \\ &= \frac{1 \cdot 1}{1 + 1} \\ &= \frac{1}{2}. \end{align*}
\begin{align*} S_4 &= \frac{S_2 \cdot S_3}{S_2 + S_3} \\ &= \frac{1 \cdot \frac{1}{2}}{1 + \frac{1}{2}} \\ &= \frac{\frac{1}{2}}{\frac{3}{2}} \\ &= \frac{1}{3}. \end{align*}
We continue in this manner until we reach $S_{12}.$
\begin{align*} S_5 &= \frac{S_3 \cdot S_4}{S_3 + S_4} \\ &= \frac{\frac{1}{2} \cdot \frac{1}{3}}{\frac{1}{2} + \frac{1}{3}} \\ &= \frac{\frac{1}{6}}{\frac{5}{6}} \\ &= \frac{1}{5}. \end{align*}
\begin{align*} S_6 &= \frac{S_4 \cdot S_5}{S_4 + S_5} \\ &= \frac{\frac{1}{3} \cdot \frac{1}{5}}{\frac{1}{3} + \frac{1}{5}} \\ &= \frac{\frac{1}{15}}{\frac{8}{15}} \\ &= \frac{1}{8}. \end{align*}
